package com.careflow.hospital.scheduling;
import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/doctors/me") @PreAuthorize("hasRole('DOCTOR')") public class DoctorScheduleController {private final DoctorScheduleService service;public DoctorScheduleController(DoctorScheduleService service){this.service=service;}@GetMapping("/schedules")List<ScheduleDtos.ScheduleView> schedules(Authentication auth){return service.schedules(user(auth));}@PostMapping("/schedules")ResponseEntity<ScheduleDtos.ScheduleView> createSchedule(Authentication auth,@Valid @RequestBody ScheduleDtos.CreateSchedule request){return ResponseEntity.status(HttpStatus.CREATED).body(service.createSchedule(user(auth),request));}@DeleteMapping("/schedules/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void removeSchedule(Authentication auth,@PathVariable UUID id){service.removeSchedule(user(auth),id);}@GetMapping("/schedule-exceptions")List<ScheduleDtos.ExceptionView> exceptions(Authentication auth){return service.exceptions(user(auth));}@PostMapping("/schedule-exceptions")ResponseEntity<ScheduleDtos.ExceptionView> createException(Authentication auth,@Valid @RequestBody ScheduleDtos.CreateException request){return ResponseEntity.status(HttpStatus.CREATED).body(service.createException(user(auth),request));}@DeleteMapping("/schedule-exceptions/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void removeException(Authentication auth,@PathVariable UUID id){service.removeException(user(auth),id);}private UUID user(Authentication auth){return UUID.fromString(auth.getName());}}
